def _list(store, user, query=""):
    notes = store.list_for_owner(user)
    params = parse_qs(query, keep_blank_values=True)
    if "q" in params:
        wanted = params["q"][0].casefold()
        if not wanted:
            return _error(400, "q must not be empty")
        notes = [note for note in notes if wanted in note.title.casefold() or wanted in note.body.casefold()]
    return _json(200, {"items": [_show(note) for note in notes]})
